from pathlib import Path
import base64,hashlib,json
ROOT=Path.cwd();PROTO=ROOT/'英文小论文/code/warm_stem_prototype_20261011_v2'
OUT=ROOT/'outputs/warm_stem_prototype_20261011_v2'
OBS=ROOT/'outputs/stem_observation_file_transport_20261011_v1'
REF=ROOT/'outputs/native_stem_scratch12_20261011_v3'
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
read=lambda p:json.loads(Path(p).read_bytes())
def write(p,x):
 with Path(p).open('x',encoding='utf8') as f:json.dump(x,f,indent=2,allow_nan=False)
inputs=json.loads(r'''{"cpu":{"1":{"base64":"","sha256":"573bf77fee76090a716953a856e1c07e6935d3f7d4a9e9ee315a313ef63b0869","bytes":4606},"2":{"base64":"","sha256":"9cfff6ff37ff305f45327f41ec7a507f52634ce63350d498e92495c00ab1eb2f","bytes":4604}},"reference":{"1":{"base64":"","expected_sha256":"ea697c9c0a7a5c0b09cacbf61437cb0f2b467d70df47454ebe3f649b3a62d0ce","expected_bytes":3037},"2":{"base64":"","expected_sha256":"722f9620ef09c6b098dce5e8e9b9fc7e68ff3270fede3c7a06b2c5e54b847296","expected_bytes":3050}},"observer_meta":{"1":{"base64":"","expected_sha256":"cfaa4fa229b42b7f51da9c451a6ea8d163622c96ac3267a29679e0497d17aeb3","expected_bytes":589},"2":{"base64":"","expected_sha256":"99e41a0ad36609fb9dd2337a2cb36bf9d41a71017852903f2e03b73dc452037e","expected_bytes":588}}}''')
expected=read(PROTO/'protocol.json')['files_sha256']|{'protocol.json':sha(PROTO/'protocol.json')}
cpus={};refs={};metas={};transport={};raws={}
for kind in ('cpu','reference','observer_meta'):
 for seed in (1,2):
  d=inputs[kind][str(seed)];b=base64.b64decode(d['base64'],validate=True)
  size=d.get('bytes',d.get('expected_bytes'));digest=d.get('sha256',d.get('expected_sha256'))
  assert len(b)==size and hashlib.sha256(b).hexdigest()==digest
  o=json.loads(b);assert o['seed']==seed
  raws[kind+str(seed)]=b;transport[kind+str(seed)]=dict(bytes=size,sha256=digest)
  if kind=='cpu':
   assert o['exit_code']==0 and o['code_sha256']==expected and not o['training_launched']
   r=o['report'];assert r['files_sha256']=={k:v for k,v in expected.items() if k!='protocol.json'} and r['protocol_sha256']==expected['protocol.json']
   # CPU report excludes protocol.json in files_sha256, as its frozen manifest does.
   cpus[str(seed)]=o
  elif kind=='reference':
   assert o['code_sha256_verified'] and not o['failures']
   assert all(p['same_live'] for p in o['processes'].values())
   assert o['completed_epochs']==o['latest_metrics']['epoch']+1
   refs[str(seed)]=o
  else:
   assert o['same_observer_source_sha256']==sha(OBS/'observe_payload64_exact_executed_v1.py')
   assert o['no_model_forwards'] and o['no_training_restarts']
   path=OBS/f'seed{seed}_observation_v3.payload.json'
   assert path.stat().st_size==o['payload_bytes'] and sha(path)==o['payload_sha256']
   metas[str(seed)]=o
assert not OUT.exists()
OUT.mkdir()
for seed in (1,2):
 with (OUT/f'remote_CPU_execution_seed{seed}_v1.json').open('xb') as f:f.write(raws['cpu'+str(seed)])
 with (REF/f'compact_payload_seed{seed}_v11.json').open('xb') as f:f.write(raws['reference'+str(seed)])
 with (OBS/f'seed{seed}_metadata_v3.json').open('xb') as f:f.write(raws['observer_meta'+str(seed)])
write(REF/'compact_observation_v11.json',refs)
write(REF/'compact_transport_v11.json',{str(s):transport['reference'+str(s)] for s in (1,2)})
write(OBS/'observation_transport_v3.json',dict(schema='stem_live_observation_transport_v1',
 observer_source='outputs/stem_observation_file_transport_20261011_v1/observe_payload64_exact_executed_v1.py',
 payloads={str(s):dict(file=f'seed{s}_observation_v3.payload.json',bytes=metas[str(s)]['payload_bytes'],sha256=metas[str(s)]['payload_sha256']) for s in (1,2)},
 scope='Same read-only observer/source and actual raw JSON bytes; no training restarted.'))
write(OUT/'transport_verification_v1.json',dict(status='PASS_BOTH_CPU_EXECUTION_BYTES_AND_PROTOCOL_SOURCE_SHA256',
 records={str(s):transport['cpu'+str(s)] for s in (1,2)},files_sha256=expected))
results=[o['report'] for o in cpus.values()]
assert all(r['status']=='PASS_CPU_ORIGINAL794_TENSORS_RNG_ZERO_GAIN_OUTPUT_NATIVE_GRADIENTS_AND_ACTIVE_RESIDUAL_GRAPH' for r in results)
assert all(r['provenance']['exact_original_tensors']==794 and r['provenance']['new_initialized_states_preserved']==78 for r in results)
assert all(r['optimizer_steps']==r['training_epochs']==r['evaluator_calls']==0 for r in results)
assert all(r['actual_forward_counts']['prototype_detector']==r['actual_forward_counts']['native_detector']==0 for r in results)
assert all(not r['CUDA_initialized'] and not r['actual_12epoch_training_launched'] for r in results)
assert all(r['zero_gain_native_training_output_exact'] and r['zero_gain_native_BN_updates_exact'] and r['zero_gain_native_gradients_exact'] for r in results)
write(OUT/'CPU_validation_summary_v1.json',dict(status='PASS_BOTH_CPU_ENGINEERING_CHECKS_ONLY',seeds=results,
 new_optimizer_updates=0,new_training_epochs=0,prototype_detector_forwards=0,baseline_detector_forwards=0,
 full_detector_predictions_verified=False,CUDA_AMP_preflight_passed=False,
 AP_improvement_proven=False,causal_root_proven=False,novelty_proven=False))
write(OUT/'execution_state_v1.json',dict(status='ISOLATED_MODEL_PROTOTYPE_CPU_VALIDATED_BOTH_SEEDS_NOT_TRAINING_READY',
 previous_goal_turn='progress',current_goal_turn='progress',no_progress_streak=0,goal_complete=False,
 prototype='英文小论文/code/warm_stem_prototype_20261011_v2',verification='CPU_validation_summary_v1.json',
 original_native_tensors_retained=794,new_parameters=11815,new_parameter_percent=100*11815/10231997,
 training_launched=False,actual_training_epochs=0,model_training_runtime_prepared=False,CUDA_AMP_preflight_passed=False,
 next='Complete current reference/component endpoints; integrate this distinct candidate into an isolated12-epoch native training/closeout package and validate CUDA AMP before resource-authorized launch. Keep original cachedBASE acceptance gates.'))
print(json.dumps(dict(status='CPU_AND_LIVE_TRANSPORT_PERSISTED',CPU_status='PASS_BOTH',reference_epochs={k:v['completed_epochs'] for k,v in refs.items()})))

